<?php declare(strict_types=1); namespace Annam; $title='Menu · '.$store->name();$chosen=(string)($_GET['slot']??($menus[0]['slot']['key']??''));if(!in_array($chosen,array_column(array_column($menus,'slot'),'key'),true))$chosen=$menus[0]['slot']['key']??''; ?>
<section class="wrap php-store-section php-menu-page"><div class="page-intro menu-page-intro"><p class="section-kicker">Cooked fresh for your slot</p><h1>What’s cooking</h1><p>Combine Breakfast, Lunch and Snacks for the same delivery date. Dinner requires a separate order. Delivery is charged once per order.</p></div><div class="filters"><div class="tabs" role="group" aria-label="Delivery day"><?php foreach([date('Y-m-d')=>'Today',date('Y-m-d',strtotime('+1 day'))=>'Tomorrow'] as $d=>$label):?><a class="tab <?= $date===$d?'on':'' ?>" href="?date=<?= e($d) ?>&slot=<?= e($chosen) ?>"><?= e($label) ?></a><?php endforeach;?></div><div class="tabs tabs-slot" role="group" aria-label="Meal"><?php foreach($menus as $m):?><a class="tab <?= $chosen===$m['slot']['key']?'on':'' ?>" href="?date=<?= e($date) ?>&slot=<?= e($m['slot']['key']) ?>"><?= e($m['slot']['label']) ?><?php if(!Delivery::slotOpen($m['slot'],$date)):?><small>view only</small><?php endif;?></a><?php endforeach;?></div></div>
<?php foreach($menus as $meal):if($chosen!==$meal['slot']['key'])continue;$slotId=(int)$meal['slot']['id'];?><section class="php-store-section php-menu-items"><h2 class="sr-only"><?= e($meal['slot']['label']) ?></h2><p class="slot-meta"><span><svg class="ic"><use href="#i-clock"/></svg>Delivered <?= e($meal['slot']['delivery_from']?date('g:i A',strtotime($meal['slot']['delivery_from'])):'at your meal slot') ?></span><span>Order by <?= e(date('g:i A',strtotime($meal['slot']['order_cutoff']))) ?></span></p><?php if(!Delivery::slotOpen($meal['slot'],$date)):?><div class="notice">This meal’s ordering window is closed or has not opened yet. Check the configured opening time and cutoff (India time).</div><?php endif;?><ul class="dishes php-product-grid"><?php foreach($meal['items'] as $product)require __DIR__.'/card.php';?></ul><?php if(!$meal['items']):?><p class="empty">No dishes are available for this meal. Please check another date.</p><?php endif;?></section><?php endforeach;?></section>
